/**
 * Webhook secrets and safe serialisation for `enterprise_connections`.
 *
 * Each connection has its own inbound webhook secret (auth_credentials.
 * webhookSecret), generated by Fleet360 and shown once, when the connection
 * is created or the secret is rotated. It is the only credential the inbound
 * webhook accepts: the ERP's own API key or token is a credential *for the
 * ERP* and must not also let callers into Fleet360.
 */
import crypto from 'crypto';

export function generateWebhookSecret(): string {
  return `whsec_${crypto.randomBytes(32).toString('base64url')}`;
}

export function parseJson(value: unknown): Record<string, unknown> {
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === 'object' ? (parsed as Record<string, unknown>) : {};
    } catch {
      return {};
    }
  }
  return value && typeof value === 'object' ? (value as Record<string, unknown>) : {};
}

/** The connection's inbound webhook secret, or null when it has none. */
export function webhookSecretOf(authCredentials: unknown): string | null {
  const secret = parseJson(authCredentials).webhookSecret;
  return typeof secret === 'string' && secret.length >= 16 ? secret : null;
}

/** Header names are shown; their values may be tokens and are not. */
function maskHeaders(headers: unknown): Record<string, string> {
  return Object.fromEntries(Object.keys(parseJson(headers)).map((name) => [name, '••••••']));
}

/**
 * A connection row as returned to the browser: never auth_credentials, never
 * header values. `hasWebhookSecret` tells the UI whether webhooks will be
 * accepted.
 */
export function toPublicConnection(c: Record<string, unknown>) {
  return {
    id: c.id,
    systemName: c.system_name,
    systemType: c.system_type,
    baseUrl: c.base_url,
    authType: c.auth_type,
    headers: maskHeaders(c.headers),
    fieldMappings: parseJson(c.field_mappings),
    isActive: c.is_active,
    rateLimitPerMin: c.rate_limit_per_min,
    healthStatus: c.health_status,
    healthMessage: c.health_message,
    lastSyncAt: c.last_sync_at,
    createdAt: c.created_at,
    hasWebhookSecret: webhookSecretOf(c.auth_credentials) !== null,
  };
}

/** Constant-time comparison of two secrets. */
export function secretsMatch(a: string, b: string): boolean {
  const ha = crypto.createHash('sha256').update(a).digest();
  const hb = crypto.createHash('sha256').update(b).digest();
  return crypto.timingSafeEqual(ha, hb) && a.length === b.length;
}
